#!/usr/bin/env bash
# Emit-provenance audit.
#
# The canonical emitted artifact is GENERATED by the verified compiler from a
# LowCT / Com jasminDialect source (golden path: FieldEmitGoldenPath.lean). A
# hand-authored `List (JInstr _)` block + direct `runBlock` proof is permitted only
# as a KAT oracle / bench prototype, and MUST tag its module docstring `@kat-target`
# or `@bench-only`.
#
# RATCHET: the current hand-JInstr corpus is grandfathered in
# scripts/emit_provenance_baseline.txt. This audit FAILS if a NEW untagged
# hand-JInstr emission file appears that is not in the baseline — new field ops
# must be tagged or generated via the golden path. (Removing a baseline file and
# regenerating it through the compiler is encouraged; the ratchet only forbids growth.)
#
# A module over a block the owned backend printed and Ascent/Imported translated back
# (@reimported, or located in Ascent/Imported/) writes no artifact and is admitted.
#
# Two further classes are admitted, each counted in its own list:
#
#   @imported [theorems: t1, t2]    a block translated from third-party assembly
#                                   (s2n-bignum, CryptOpt); listed in
#                                   scripts/imported-kernel-baseline.txt. A block with
#                                   no named theorem is a trusted leaf.
#   @proved-hand-kernel theorems: t1, t2
#                                   a hand-written block whose encoded bytes ship; at
#                                   least one named correctness theorem, and listed in
#                                   scripts/proved-hand-kernel-baseline.txt, the list of
#                                   kernels scheduled to be generated by a front.
#
# Every theorem a tag names must be declared under CatCrypt/.
#
# Run before commit:  bash scripts/audit_emit_provenance.sh
set -euo pipefail
cd "$(dirname "$0")/.."

# The pattern requires a definition BODY: `def f : List (JInstr n) := …`. Without the
# `:=` it also matched a parser whose ARGUMENT is a block, e.g.
# `def parseBlock : List (JInstr 64) -> Option (List RawArith)`, which authors nothing.
# Measured over CatCrypt/ and bench/: 126 files match without it, 121 with; of the five
# dropped, four sit in the wholesale-exempt `X86Backend/` and `bench/` trees, so exactly
# one module's verdict changes and its matches are argument types.
pattern='def [A-Za-z0-9_]* *: *List \(JInstr [0-9]*\) *:='
baseline=scripts/emit_provenance_baseline.txt
imported_list=scripts/imported-kernel-baseline.txt
proved_list=scripts/proved-hand-kernel-baseline.txt

# The theorem names after `theorems:` on the tag line of $2 in file $1.
tag_theorems() {
  grep -m1 -oE "$2[^\`]*theorems:[^\`]*" "$1" | sed 's/.*theorems://' | tr ',' ' '
}
# 0 iff every theorem named by the tag $2 in $1 is declared under CatCrypt/.
tag_theorems_exist() {
  local t ok=0
  for t in $(tag_theorems "$1" "$2"); do
    if ! grep -rqE "^(private |protected )?theorem ${t}([[:space:]]|$)" CatCrypt/ 2>/dev/null; then
      echo "EMIT-PROVENANCE: $1 names theorem '$t' in its $2 tag; no such theorem"
      ok=1
    fi
  done
  return $ok
}

fail=0
while IFS= read -r f; do
  [ -z "$f" ] && continue
  grep -qE '@kat-target|@bench-only' "$f" && continue           # tagged → allowed
  if grep -qE '@proved-hand-kernel' "$f"; then
    if [ -z "$(tag_theorems "$f" '@proved-hand-kernel')" ]; then
      echo "EMIT-PROVENANCE: $f is tagged @proved-hand-kernel but names no theorem"; fail=1
    fi
    tag_theorems_exist "$f" '@proved-hand-kernel' || fail=1
    grep -qxF "$f" "$proved_list" || { echo "EMIT-PROVENANCE: $f is tagged @proved-hand-kernel but is not listed in $proved_list"; fail=1; }
    continue
  fi
  if grep -qE '@imported' "$f"; then
    tag_theorems_exist "$f" '@imported' || fail=1
    grep -qxF "$f" "$imported_list" || { echo "EMIT-PROVENANCE: $f is tagged @imported but is not listed in $imported_list"; fail=1; }
    continue
  fi
  # Ascent/Imported translates an already-printed assembly file back into JInstr
  # so the ascent can prove it; such a module writes no artifact.
  case "$f" in *Ascent/Imported/*) continue ;; esac
  # @reimported: a proof module over such a re-imported block, outside that directory.
  grep -qE '@reimported' "$f" && continue
  case "$f" in *X86Backend/*|bench/*) continue ;; esac          # grandfathered infra
  grep -qxF "$f" "$baseline" && continue                        # in frozen baseline → grandfathered
  echo "EMIT-PROVENANCE: NEW untagged hand-JInstr emission in $f"
  echo "  -> tag its module docstring @kat-target/@bench-only/@imported/@proved-hand-kernel, OR generate it via the"
  echo "     golden path (Com jasminDialect -> com_arm_e2e/com_riscv_e2e)."
  fail=1
done < <(grep -rlE "$pattern" CatCrypt/ 2>/dev/null | sort)

if [ "$fail" -eq 0 ]; then
  echo "emit-provenance audit: OK (no new untagged hand-JInstr blocks; baseline = $(grep -vc '^#' "$baseline") grandfathered; imported = $(grep -vc '^#' "$imported_list"); proved hand kernels = $(grep -vc '^#' "$proved_list"))"
fi
exit $fail
